VAR
  rtBox : R_TRIG;
  bSensor : BOOL;
  nBoxes : INT;
END_VAR

rtBox(CLK := bSensor);
IF rtBox.Q THEN
  nBoxes := nBoxes + 1;
END_IF

CASE nStep OF
  0: IF bStart THEN nStep := 1; END_IF
  1: bFill := TRUE;
     IF bFull THEN bFill := FALSE; nStep := 2; END_IF
  2: bMix := TRUE;
END_CASE
